export const glassStyles = "/* Approved edge-light v4; a fully opaque, useful header is the no-JS default. */\n.ew-glass-header .ew-header__inner {\n  --ew-liquid: 0;\n  position: relative;\n  border: 0;\n  border-radius: var(--ew-glass-radius, 29px);\n  background: transparent;\n  backdrop-filter: none;\n  -webkit-backdrop-filter: none;\n  box-shadow: 0 12px 26px -17px #122a3848, 0 2px 5px #18383a14;\n  touch-action: pan-y;\n}\n.ew-liquid-layers, .ew-liquid-optics, .ew-liquid-solid, .ew-liquid-rim, .ew-liquid-light {\n  position: absolute;\n  inset: 0;\n  border-radius: inherit;\n  pointer-events: none;\n}\n/* No opacity/filter on the wrapper: that would isolate the live backdrop. */\n.ew-liquid-layers { z-index: 0; }\n.ew-liquid-defs { position: absolute; width: 0; height: 0; overflow: hidden; }\n.ew-liquid-optics {\n  background: linear-gradient(155deg, var(--ew-glass-top, #ffffff26), transparent 52%, var(--ew-glass-bottom, #d1e9e412));\n  backdrop-filter: blur(var(--ew-glass-frost, 1.2px)) saturate(var(--ew-glass-saturation, 1.2));\n  -webkit-backdrop-filter: blur(var(--ew-glass-frost, 1.2px)) saturate(var(--ew-glass-saturation, 1.2));\n}\n.ew-header__inner:not([data-glass-state]) .ew-liquid-optics,\n.ew-header__inner[data-glass-state=\"solid\"] .ew-liquid-optics { visibility: hidden; }\n.ew-liquid-solid {\n  background: var(--ew-glass-solid, #0f2530);\n  opacity: calc(1 - var(--ew-liquid));\n  box-shadow: inset 0 0 0 1px #b9d3da47, inset 0 1px 0 #ffffff19;\n}\n.ew-liquid-rim {\n  opacity: var(--ew-liquid);\n  background: linear-gradient(175deg, #ffffff0d, transparent 45%, #112e3510);\n  box-shadow: inset 0 1px 1px #ffffff40, inset 0 -1px 1px #17313920;\n}\n.ew-liquid-rim::before {\n  content: ''; position: absolute; inset: 0; padding: 1px; border-radius: inherit;\n  opacity: var(--ew-rim-energy, .42);\n  background: conic-gradient(from 135deg, #ffffffd9, #ffffff15 16%, #5d87784d 27%, #ffffff10 40%, #ffffffe8 52%, #ffffff20 65%, #283d4d66 79%, #ffffff15 90%, #ffffffd9);\n  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);\n  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);\n  -webkit-mask-composite: xor;\n  mask-composite: exclude;\n}\n.ew-liquid-light { width: 100%; height: 100%; opacity: 0; }\n.ew-glass-header .ew-brand, .ew-glass-header .ew-menu-toggle, .ew-glass-header .ew-header__cta { position: relative; z-index: 1; }\n.ew-glass-header .ew-nav { position: relative; z-index: 1; }\n.ew-glass-header .ew-nav a { position: relative; }\n.ew-glass-header .ew-header__inner a, .ew-glass-header .ew-menu-toggle { touch-action: pan-y; }\n.ew-glass-header .ew-header__inner [data-glass-tone=\"light\"] { color: #163435; text-shadow: 0 1px 3px #ffffffb0; }\n.ew-glass-header .ew-header__inner [data-glass-tone=\"dark\"] { color: #f3faf8; text-shadow: 0 1px 3px #07121bdb; }\n.ew-glass-header .ew-header__cta[data-glass-tone=\"light\"] { background: #173b3cf2; color: #f1faf5; text-shadow: none; }\n.ew-glass-header .ew-header__cta[data-glass-tone=\"dark\"] { background: #f4faf1f2; color: #17383a; text-shadow: none; }\n.ew-glass-header .ew-menu-toggle[data-glass-tone=\"light\"] { border-color: #173b3c66; }\n@media (max-width: 760px) {\n  .ew-glass-header .ew-header__inner { border-radius: var(--ew-glass-mobile-radius, 23px); }\n}\n/* Match the cinematic navigation breakpoint while retaining phone-only radii. */\n@media (max-width: 980px) {\n  .ew-glass-header .ew-nav { position: absolute; top: calc(100% + 10px); left: 0; right: 0; }\n  .ew-glass-header .ew-nav.is-open { background: #102b37; }\n}\n@media (prefers-reduced-motion: reduce) { .ew-liquid-light { display: none; } }\n@media (forced-colors: active) {\n  .ew-glass-header .ew-header__inner { background: Canvas; border: 1px solid CanvasText; }\n  .ew-liquid-layers { display: none; }\n  .ew-glass-header .ew-header__inner [data-glass-tone] { color: LinkText; text-shadow: none; }\n}\n";
export const glassMarkup = "<div class=\"ew-liquid-layers\" aria-hidden=\"true\"><svg class=\"ew-liquid-defs\" xmlns=\"http://www.w3.org/2000/svg\"><defs><filter id=\"ew-lens-_R_0_\" color-interpolation-filters=\"sRGB\" filterUnits=\"userSpaceOnUse\" primitiveUnits=\"userSpaceOnUse\" x=\"0\" y=\"0\" width=\"1450\" height=\"76\"><feImage data-lens-map=\"\" x=\"0\" y=\"0\" width=\"1450\" height=\"76\" preserveAspectRatio=\"none\" result=\"lensRaw\"></feImage><feGaussianBlur in=\"lensRaw\" stdDeviation=\"0.55\" result=\"lensMap\"></feGaussianBlur><feDisplacementMap data-base-displacement=\"\" in=\"SourceGraphic\" in2=\"lensMap\" scale=\"64\" xChannelSelector=\"R\" yChannelSelector=\"G\" result=\"baseGlass\"></feDisplacementMap><feFlood flood-color=\"#808080\" result=\"neutralContact\"></feFlood><feImage data-contact-map=\"\" x=\"0\" y=\"0\" width=\"200\" height=\"200\" preserveAspectRatio=\"none\" result=\"contactPatch\"></feImage><feImage data-edge-mask=\"\" x=\"0\" y=\"0\" width=\"1450\" height=\"76\" preserveAspectRatio=\"none\" result=\"edgeMask\"></feImage><feComposite in=\"contactPatch\" in2=\"edgeMask\" operator=\"in\" result=\"edgeContact\"></feComposite><feMerge result=\"contactRaw\"><feMergeNode in=\"neutralContact\"></feMergeNode><feMergeNode in=\"edgeContact\"></feMergeNode></feMerge><feComponentTransfer in=\"contactRaw\" result=\"contactField\"><feFuncR type=\"linear\" slope=\"1\" intercept=\"-0.0019607843\"></feFuncR><feFuncG type=\"linear\" slope=\"1\" intercept=\"-0.0019607843\"></feFuncG></feComponentTransfer><feDisplacementMap data-contact-displacement=\"\" in=\"baseGlass\" in2=\"contactField\" scale=\"0\" xChannelSelector=\"R\" yChannelSelector=\"G\"></feDisplacementMap></filter></defs></svg><div class=\"ew-liquid-optics\"></div><div class=\"ew-liquid-solid\"></div><div class=\"ew-liquid-rim\"></div><canvas class=\"ew-liquid-light\"></canvas></div>";
